// Validate the inbound lead payload and attach a unique run_id.
// Every downstream node reads from this node, not from the Webhook,
// so normalization happens in one place.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const body = item.json.body || {};

  // Required fields
  const name = (body.name || '').trim();
  const email = (body.email || '').trim().toLowerCase();
  const companyDomain = (body.company_domain || '').trim().toLowerCase();
  const message = (body.message || '').trim();

  // Validation
  const errors = [];
  if (!name) errors.push('name is required');
  if (!email) errors.push('email is required');
  if (!email.includes('@')) errors.push('email is not a valid address');
  if (!companyDomain) errors.push('company_domain is required');
  if (!companyDomain.includes('.')) errors.push('company_domain must include a TLD');

  if (errors.length > 0) {
    results.push({
      json: {
        valid: false,
        errors: errors,
        run_id: $execution.id + '-' + i + '-' + Date.now(),
        received_at: new Date().toISOString()
      }
    });
    continue;
  }

  // Strip protocol and www if present
  const cleanDomain = companyDomain
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/.*$/, '');

  results.push({
    json: {
      valid: true,
      errors: [],
      run_id: $execution.id + '-' + i + '-' + Date.now(),
      received_at: new Date().toISOString(),
      lead: {
        name: name,
        email: email,
        company_domain: cleanDomain,
        message: message
      }
    }
  });
}

return results;

// Reshape the Apify response into the enrichment signals Groq will score against.
// Reads from Validate Lead Payload for lead identity and from Apify output for company signals.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const enrich = item.json || {};

  // Reach back to the validated lead payload for identity fields
  const lead = $('Validate Lead Payload').item.json.lead;

  // Guard against a completely empty Apify response
  if (!enrich || Object.keys(enrich).length === 0) {
    results.push({
      json: {
        run_id: $('Validate Lead Payload').item.json.run_id,
        received_at: $('Validate Lead Payload').item.json.received_at,
        lead: lead,
        enrichment: {
          domain: lead.company_domain,
          title: null,
          description: null,
          domain_age: null,
          registrar: null,
          social_links_present: false,
          technologies_count: 0,
          contact_email_present: false,
          contact_phone_present: false
        },
        enrichment_available: false,
        enrichment_summary: "Apify returned empty response"
      }
    });
    continue;
  }

  // Pull each signal with null-safe access
  const title = (enrich.metadata && enrich.metadata.title) || null;
  const description = (enrich.metadata && enrich.metadata.description) || null;
  const domainAge = (enrich.domainInfo && enrich.domainInfo.domainAge) || null;
  const registrar = (enrich.domainInfo && enrich.domainInfo.registrar) || null;
  const socialLinks = enrich.socialLinks && typeof enrich.socialLinks === 'object'
    ? Object.keys(enrich.socialLinks).length > 0
    : false;
  const technologies = Array.isArray(enrich.technologies) ? enrich.technologies : [];
  const contactEmails = enrich.contact && enrich.contact.emails ? enrich.contact.emails : null;
  const contactPhones = enrich.contact && enrich.contact.phones ? enrich.contact.phones : null;

  results.push({
    json: {
      run_id: $('Validate Lead Payload').item.json.run_id,
      received_at: $('Validate Lead Payload').item.json.received_at,
      lead: lead,
      enrichment: {
        domain: enrich.domain || lead.company_domain,
        title: title,
        description: description,
        domain_age: domainAge,
        registrar: registrar,
        social_links_present: socialLinks,
        technologies_count: technologies.length,
        contact_email_present: contactEmails !== null,
        contact_phone_present: contactPhones !== null
      },
      enrichment_available: title !== null || description !== null || domainAge !== null,
      enrichment_summary: buildSummary(title, description, domainAge, socialLinks, technologies)
    }
  });
}

// Build a short human-readable summary for the Groq prompt
function buildSummary(title, description, domainAge, socialLinks, technologies) {
  const parts = [];
  if (title) parts.push("Title: " + title);
  if (description) parts.push("Description: " + description.slice(0, 200));
  if (domainAge) parts.push("Domain age: " + domainAge);
  parts.push("Social links: " + (socialLinks ? "present" : "none"));
  parts.push("Tech stack: " + (technologies.length > 0 ? technologies.slice(0, 5).join(", ") : "unknown"));
  return parts.join(" | ");
}

return results;

// Assemble the full Groq API request body as a JSON string.
// Sent as raw body by the next node.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const lead = item.json.lead;
  const enrichment = item.json.enrichment;
  const run_id = item.json.run_id;

  // Countable criteria for lead scoring.
  // high = 2 or more criteria met. medium = 1. low = 0.
  const systemPrompt = [
    "You are a lead qualification scorer. Score the lead against 5 countable criteria and return JSON only.",
    "",
    "Criteria:",
    "1. Decision-Maker Role: the message or contact name indicates the sender can approve purchasing decisions (titles: CEO, CTO, VP, Head, Director, Founder, Owner, Manager of a relevant function).",
    "2. Budget or Approval Signal: the message mentions a budget, an approved spend, a procurement process, or a paid engagement.",
    "3. Company Maturity: the enrichment shows at least 2 of: a real page title, a real page description, a domain age of 2 or more years, a populated registrar, or social links present.",
    "4. Timeline: the message names a timeframe for starting or completing the project (e.g. 'this quarter', 'by December', 'next month').",
    "5. Specific Solution Request: the message names a specific problem, tool, or process the sender wants automated or integrated.",
    "",
    "Scoring rule:",
    "- high: 2 or more criteria met",
    "- medium: exactly 1 criterion met",
    "- low: 0 criteria met",
    "",
    "Ambiguous cases lean toward the lower score, not the higher one. Do not infer signals that are not stated. If a criterion is unclear, mark it as not met.",
    "",
    "Return JSON only, no markdown, no prose, with this exact shape:",
    '{"score":"high|medium|low","criteria_met":["Criterion Name",...],"reasoning":"one sentence"}'
  ].join("\n");

  const userPrompt = [
    "Lead name: " + lead.name,
    "Lead email: " + lead.email,
    "Company domain: " + lead.company_domain,
    "Message: " + lead.message,
    "",
    "Enrichment summary:",
    item.json.enrichment_summary,
    "",
    "Enrichment signals:",
    "- Domain age: " + (enrichment.domain_age || "unknown"),
    "- Registrar: " + (enrichment.registrar || "unknown"),
    "- Social links present: " + enrichment.social_links_present,
    "- Technologies count: " + enrichment.technologies_count,
    "- Contact email present: " + enrichment.contact_email_present,
    "- Contact phone present: " + enrichment.contact_phone_present
  ].join("\n");

  const body = {
    model: "openai/gpt-oss-20b",
    temperature: 0,
    reasoning_effort: "low",
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt }
    ]
  };

  results.push({
    json: {
      run_id: run_id,
      received_at: item.json.received_at,
      lead: lead,
      enrichment: enrichment,
      enrichment_available: item.json.enrichment_available,
      enrichment_summary: item.json.enrichment_summary,
      body_string: JSON.stringify(body)
    }
  });
}

return results;

// Parse the Groq response and merge the score with the lead and enrichment data.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const groqResponse = item.json;

  const previous = $('Build Groq Body').first().json;

  let score = "unknown";
  let criteriaMet = [];
  let reasoning = "Parse failed";
  let parseError = null;

  try {
    const content = groqResponse.choices[0].message.content;
    const parsed = JSON.parse(content);
    score = parsed.score || "unknown";
    criteriaMet = Array.isArray(parsed.criteria_met) ? parsed.criteria_met : [];
    reasoning = parsed.reasoning || "";
  } catch (e) {
    parseError = e.message;
  }

  const validScores = ["high", "medium", "low"];
  if (!validScores.includes(score)) {
    score = "unknown";
  }

  // Build a Postgres-compatible array literal for criteria_met
  const esc = (v) => "'" + String(v).replace(/'/g, "''") + "'";
  const criteriaMetSql = criteriaMet.length > 0
    ? "ARRAY[" + criteriaMet.map(esc).join(",") + "]::text[]"
    : "ARRAY[]::text[]";

  results.push({
    json: {
      run_id: previous.run_id,
      received_at: previous.received_at,
      lead: previous.lead,
      enrichment: previous.enrichment,
      enrichment_available: previous.enrichment_available,
      enrichment_summary: previous.enrichment_summary,
      score: score,
      criteria_met: criteriaMet,
      criteria_met_sql: criteriaMetSql,
      reasoning: reasoning,
      parse_error: parseError,
      groq_usage: {
        prompt_tokens: groqResponse.usage ? groqResponse.usage.prompt_tokens : null,
        completion_tokens: groqResponse.usage ? groqResponse.usage.completion_tokens : null,
        reasoning_tokens: groqResponse.usage && groqResponse.usage.completion_tokens_details
          ? groqResponse.usage.completion_tokens_details.reasoning_tokens
          : null,
        total_tokens: groqResponse.usage ? groqResponse.usage.total_tokens : null
      }
    }
  });
}

return results;

// Replaces the Filter node due to a comparison bug in n8n 2.8.4.
// The Filter node discarded items whose score matched the condition.
// This Code node uses strict JavaScript equality, which is deterministic.

const items = $input.all();
const kept = [];

for (const item of items) {
  if (item.json.score === 'high') {
    kept.push(item);
  }
}

return kept;
